function readSavedData(): AppData {
  try {
    const saved = localStorage.getItem("fishlink-data-v2");

    if (!saved) return initialData;

    const parsed = JSON.parse(saved);
    const savedMessages: Message[] = parsed.messages?.length
      ? parsed.messages
      : starterMessages;

    return {
      ...initialData,
      ...parsed,
      listings: parsed.listings?.length
        ? parsed.listings
        : starterListings,
      messages: savedMessages.map((message) => ({
        ...message,
        group: message.group || "general",
      })),
    };
  } catch {
    return initialData;
  }
}

