                      <label>
                        Pond Name
                        <input
                          name="pondName"
                          placeholder="Pond 1"
                          required
                        />
                      </label>

                      <label>
                        Fish Population
                        <input
                          name="population"
                          type="number"
                          min="1"
                          required
                        />
                      </label>

                      <div className="form-two">
                        <label>
                          Length (m)
                          <input
                            name="length"
                            type="number"
                            min="0.1"
                            step="0.1"
                            required
                          />
                        </label>

                        <label>
                          Width (m)
                          <input
                            name="width"
                            type="number"
                            min="0.1"
                            step="0.1"
                            required
                          />
                        </label>
                      </div>

                      <div className="form-actions">
                        <Button type="submit">Save Pond</Button>

                        <Button
                          outline
                          onClick={() => setShowPondForm(false)}
                        >
                          Cancel
                        </Button>
                      </div>
                    </form>
                  )}

                  <label className="filter-label">
                    Filter by farm

                    <select
                      value={selectedFarm}
                      onChange={(event) =>
                        setSelectedFarm(event.target.value)
                      }
                    >
                      <option value="">All farms</option>

                      {data.farms.map((farm) => (
                        <option
                          key={farm.id}
                          value={farm.id}
                        >
                          {farm.name}
                        </option>
                      ))}
                    </select>
                  </label>

                  {farmPonds.length === 0 ? (
                    <Empty
                      title="No ponds added yet"
                      description="Add a farm, then register its ponds."
                      icon="🐟"
                    />
                  ) : (
                    farmPonds.map((pond) => (
                      <article
                        className="pond-card"
                        key={pond.id}
                      >
                        <div className="pond-art">🐟</div>

                        <div className="pond-info">
                          <div className="pond-title">
                            <strong>{pond.name}</strong>
                            <span className="status-pill">
                              {pond.status}
                            </span>
                          </div>

                          <small>
                            {
                              data.farms.find(
                                (farm) => farm.id === pond.farmId
                              )?.name
                            }{" "}
                            · Catfish
                          </small>

                          <p>
                            {pond.population.toLocaleString()} fish ·{" "}
                            {pond.length} × {pond.width} m
                          </p>
                        </div>

                        <button
                          className="delete-icon"
                          onClick={() => deletePond(pond.id)}
                          aria-label={`Delete ${pond.name}`}
                        >
                          ×
                        </button>
                      </article>
                    ))
                  )}
                </>
              )}

              {/* PRODUCTION TAB */}

              {farmTab === "production" && (
                <section className="panel">
                  <div className="panel-heading">
                    <div>
                      <h2>Feeding Records</h2>
                      <p>
                        Track feed quantities and feeding dates.
                      </p>
                    </div>

                    <Button
                      disabled={!data.ponds.length}
                      onClick={() =>
                        setShowFeedForm((old) => !old)
                      }
                    >
                      + Record Feeding
                    </Button>
                  </div>

                  {showFeedForm && (
                    <form
                      className="entry-form"
                      onSubmit={addFeeding}
                    >
                      <h3>Record Feeding</h3>

                      <label>
                        Pond

                        <select
                          name="pondId"
                          required
                          defaultValue=""
                        >
                          <option value="">Choose a pond</option>

                          {data.ponds.map((pond) => (
                            <option
                              key={pond.id}
                              value={pond.id}
                            >
                              {pond.name}
                            </option>
                          ))}
                        </select>
                      </label>

                      <label>
                        Feed Quantity (kg)

                        <input
                          name="amount"
                          type="number"
                          min="0.1"
                          step="0.1"
                          required
                        />
                      </label>

                      <label>
                        Date

                        <input
                          name="date"
                          type="date"
                          defaultValue={today()}
                          required
                        />
                      </label>

                      <div className="form-actions">
                        <Button type="submit">
                          Save Record
                        </Button>

                        <Button
                          outline
                          onClick={() => setShowFeedForm(false)}
                        >
                          Cancel
                        </Button>
                      </div>
                    </form>
                  )}

                  {recentFeedings.length === 0 ? (
                    <Empty
                      title="No feeding records"
                      description="Record your first feeding activity."
                      icon="🌾"
                    />
                  ) : (
                    recentFeedings.map((record) => (
                      <div
                        className="record-row"
                        key={record.id}
                      >
                        <span className="record-icon">🌾</span>

                        <div className="record-main">
                          <strong>
                            {
                              data.ponds.find(
                                (pond) => pond.id === record.pondId
                              )?.name
                            }
                          </strong>

                          <small>{record.date}</small>
                        </div>

                        <strong>{record.amount} kg</strong>
                      </div>
                    ))
                  )}
                </section>
              )}

              {/* WATER MONITORING TAB */}

              {farmTab === "water" && (
                <section className="panel">
                  <div className="panel-heading">
                    <div>
                      <h2>Water Monitoring</h2>
                      <p>Record water quality measurements.</p>
                    </div>

                    <Button
                      disabled={!data.ponds.length}
                      onClick={() =>
                        setShowReadingForm((old) => !old)
                      }
                    >
                      + Add Reading
                    </Button>
                  </div>

                  {showReadingForm && (
                    <form
                      className="entry-form"
                      onSubmit={addReading}
                    >
                      <h3>New Water Reading</h3>

                      <label>
                        Pond

                        <select
                          name="pondId"
                          required
                          defaultValue=""
                        >
                          <option value="">Choose a pond</option>

                          {data.ponds.map((pond) => (
                            <option
                              key={pond.id}
                              value={pond.id}
                            >
                              {pond.name}
                            </option>
                          ))}
                        </select>
                      </label>

                      <div className="form-two">
                        <label>
                          Temperature (°C)

                          <input
                            name="temperature"
                            type="number"
                            step="0.1"
                            required
                          />
                        </label>

                        <label>
                          Dissolved Oxygen (mg/L)

                          <input
                            name="oxygen"
                            type="number"
                            step="0.1"
                            required
                          />
                        </label>

                        <label>
                          pH

                          <input
                            name="ph"
                            type="number"
                            step="0.1"
                            required
                          />
                        </label>

                        <label>
                          Water Level (%)

                          <input
                            name="level"
                            type="number"
                            min="0"
                            max="100"
                            step="0.1"
                            required
                          />
                        </label>

                        <label>
                          Turbidity (NTU, optional)

                          <input
                            name="turbidityNtu"
                            type="number"
                            min="0"
                            step="0.1"
                          />
                        </label>
                      </div>

                      <div className="form-actions">
                        <Button type="submit">
                          Save Reading
                        </Button>

                        <Button
                          outline
                          onClick={() => setShowReadingForm(false)}
                        >
                          Cancel
                        </Button>
                      </div>
                    </form>
                  )}

                  {recentReadings.length === 0 ? (
                    <Empty
                      title="No water readings"
                      description="Add a reading manually. Sensor data can be integrated later."
                      icon="💧"
                    />
                  ) : (
                    recentReadings.map((reading) => (
                      <div
                        className="record-row"
                        key={reading.id}
                      >
                        <span className="record-icon">💧</span>

                        <div className="record-main">
                          <strong>
                            {
                              data.ponds.find(
                                (pond) => pond.id === reading.pondId
                              )?.name
                            }
                          </strong>

                          <small>
                            {new Date(reading.date).toLocaleString()}
                          </small>

                          <small>
                            {reading.temperature}°C ·{" "}
                            {reading.oxygen} mg/L DO · pH{" "}
                            {reading.ph} · {reading.level}%
                            {reading.turbidityNtu !== null &&
                            reading.turbidityNtu !== undefined
                              ? ` · ${reading.turbidityNtu} NTU`
                              : ""}
                          </small>
                        </div>
                      </div>
                    ))
                  )}

                  <div className="notice">
                    Readings saved to your account are available to the
                    live pond visualization. Water level is stored as a
                    percentage from 0 to 100.
                  </div>
                </section>
              )}

              {/* POND SIMULATION TAB: animation is supplied by the simulation team */}
              {farmTab === "simulation" && (
                <PondSimulation
                  farms={data.farms}
                  ponds={data.ponds}
                />
              )}
            </>
          )}

          {/* MARKETPLACE */}

          {page === "marketplace" && (
            <>
              <Heading
                title="Marketplace"
                description="Discover fish, feed, fingerlings, equipment and farming services."
              />

              <section className="panel">
                <input
                  className="search-box"
                  placeholder="Search products and services..."
                  value={search}
                  onChange={(event) =>
                    setSearch(event.target.value)
                  }
                />

                <div className="category-grid">
                  {categories.map((item) => (
                    <button
                      key={item}
                      className={`category-button ${
                        category === item ? "chosen" : ""
                      }`}
                      onClick={() => setCategory(item)}
                    >
                      <span>
                        {
                          {
                            All: "🌐",
                            Fish: "🐟",
                            Feed: "🌾",
                            Fingerlings: "🐠",
                            Equipment: "⚙️",
                            Services: "🛠️",
                          }[item]
                        }
                      </span>

                      {item}
                    </button>
                  ))}
                </div>

                {isSeller && (
                  <form
                    className="entry-form"
                    onSubmit={addListing}
                  >
                    <h3>Publish a Listing</h3>

                    <label>
                      Product or Service

                      <input
                        name="productName"
                        required
                        placeholder="What are you selling?"
                      />
                    </label>

                    <div className="form-two">
                      <label>
                        Category

                        <select name="category">
                          {categories
                            .filter((item) => item !== "All")
                            .map((item) => (
                              <option key={item}>{item}</option>
                            ))}
                        </select>
                      </label>

                      <label>
                        Price (₦)

                        <input
                          name="price"
                          type="number"
                          min="1"
                          required
                        />
                      </label>
                    </div>

                    <label>
                      Description

                      <input
                        name="description"
                        placeholder="Product details"
                      />
                    </label>

                    <Button type="submit">
                      Publish Listing
                    </Button>
                  </form>
                )}

                <div className="panel-heading">
                  <div>
                    <h2>Featured Products</h2>
                    <p>
                      {visibleListings.length} items available
                    </p>
                  </div>
                </div>

                {visibleListings.length === 0 ? (
                  <Empty
                    title="No matching products"
                    description="Try another category or search."
                    icon="🛒"
                  />
                ) : (
                  <div className="listing-grid">
                    {visibleListings.map((listing) => (
                      <article
                        className="listing-card"
                        key={listing.id}
                      >
                        <div className="listing-art">
                          {listing.emoji}
                        </div>

                        <div className="listing-body">
                          <span className="category-pill">
                            {listing.category}
                          </span>

                          <h3>{listing.name}</h3>

                          <p>{listing.description}</p>

                          <strong>{money(listing.price)}</strong>

                          <small>
                            Seller: {listing.seller}
                          </small>

                          <Button
                            outline
                            onClick={() =>
                              notify(
                                "Seller contact and ordering will be enabled with the backend."
                              )
                            }
                          >
                            Contact Seller
                          </Button>
                        </div>
                      </article>
                    ))}
                  </div>
                )}

                <div className="notice">
                  Featured products are illustrative prototype listings,
                  not verified live seller offers.
                </div>
              </section>
            </>
          )}

          {/* COMMUNITY */}

          {page === "community" && (
            <>
              <Heading
                title="Community"
                description="Connect with farmers, experts and fish farming professionals."
              />

              <section className="community-banner">
                <span>🌱</span>

                <div>
                  <h2>Grow Together</h2>

                  <p>
                    Share experiences, ask questions and learn from
                    the FishLink community.
                  </p>
                </div>
              </section>

              <div
                className="community-groups"
                role="tablist"
                aria-label="Community groups"
              >
                {communityGroups.map((group) => {
                  const count = data.messages.filter(
                    (message) => message.group === group.id
                  ).length;

                  return (
                    <button
                      key={group.id}
                      type="button"
                      role="tab"
                      aria-selected={communityGroup === group.id}
                      className={`community-group ${
                        communityGroup === group.id ? "active" : ""
                      }`}
                      onClick={() => {
                        setCommunityGroup(group.id);
                        setChatText("");
                      }}
                      title={group.description}
                    >
                      <strong>{group.label}</strong>
                      <span>{count}</span>
                    </button>
                  );
                })}
              </div>

              <section className="panel">
                <div className="chat-heading">
                  <span className="record-icon">💬</span>

                  <div>
                    <h2>{activeCommunityGroup.label} Group</h2>
                    <small>
                      {activeCommunityGroup.description} · Local prototype
                    </small>
                  </div>
                </div>

                <div className="chat-messages">
                  {communityMessages.length === 0 ? (
                    <div className="chat-empty">
                      No messages in this group yet. Start the conversation.
                    </div>
                  ) : (
                    communityMessages.map((message) => (
                      <div
                        className={`chat-message ${
                          message.mine ? "mine" : ""
                        }`}
                        key={message.id}
                      >
                        <strong>
                          {message.sender}{" "}
                          <small>{message.role}</small>
                        </strong>

                        <p>{message.text}</p>

                        <small>{message.date}</small>
                      </div>
                    ))
                  )}
                </div>

                <form
                  className="chat-form"
                  onSubmit={sendMessage}
                >
                  <input
                    value={chatText}
                    onChange={(event) =>
                      setChatText(event.target.value)
                    }
                    placeholder={`Message the ${activeCommunityGroup.label.toLowerCase()} group...`}
                    aria-label={`Message the ${activeCommunityGroup.label} group`}
                  />

                  <Button type="submit">Send ➤</Button>
                </form>
              </section>

              <section className="panel ai-panel">
                <div className="ai-icon">🤖</div>

                <div>
                  <h2>FishLink AI Assistant</h2>

                  <p>
                    Ask about feeding, water quality, catfish growth
                    and pond management.
                  </p>

                  <Button
                    onClick={() =>
                      notify(
                        "AI answers will be enabled when an AI backend is connected."
                      )
                    }
                  >
                    Open AI Assistant
                  </Button>
                </div>
              </section>
            </>
          )}

          {/* PROFILE */}

          {page === "profile" && (
            <>
              <Heading
                title="My Profile"
                description="Your FishLink account and preferences."
              />

              <section className="panel">
                <div className="profile-intro">
                  <span className="profile-avatar">
                    {data.user?.name.charAt(0).toUpperCase() || "G"}
                  </span>

                  <div>
                    <h2>{data.user?.name || "Guest"}</h2>

                    <p>{currentRole}</p>

                    <small>
                      {data.user?.email || "Guest account"}
                    </small>

                    {data.user?.phone && (
                      <small>{data.user.phone}</small>
                    )}
                  </div>
                </div>

                <div className="settings-row">
                  <span>Account type</span>

                  <strong>
                    {data.user?.guest ? "Guest" : "Registered account"}
                  </strong>
                </div>

                <div className="settings-row">
                  <span>Language</span>
                  <LanguageSelect />
                </div>

                <div className="settings-row">
                  <span>Farms</span>
                  <strong>{data.farms.length}</strong>
                </div>

                <div className="settings-row">
                  <span>Ponds</span>
                  <strong>{data.ponds.length}</strong>
                </div>

                <div className="settings-row">
                  <span>Fish Population</span>
                  <strong>{totalFish.toLocaleString()}</strong>
                </div>

                <Button
                  outline
                  onClick={() => go("farms")}
                >
                  Manage My Farms
                </Button>

                {localImportData && (
                  <Button
                    outline
                    onClick={importLocalRecords}
                    disabled={busy}
                  >
                    Import Local Records
                  </Button>
                )}

                <button
                  className="button button-outline logout-full danger"
                  onClick={logout}
                  disabled={busy}
                >
                    {t("logout")}
                </button>
              </section>
            </>
          )}

          <footer className="app-footer">
            FishLink · Connect · Learn · Grow
          </footer>
        </div>
      </main>

      {/* MOBILE NAVIGATION */}

      <nav className="mobile-nav">
        {navItems.map((item) => (
          <button
            key={item.id}
            className={page === item.id ? "active" : ""}
            onClick={() => go(item.id)}
          >
            <span>{item.icon}</span>
            <small>{item.label}</small>
          </button>
        ))}
      </nav>

      {/* NOTIFICATIONS */}

      {toast && (
        <div className="toast" role="status">
          {toast}
        </div>
      )}
    </div>
  );
}
